/**
 * Page Object for Leave Management
 * Source: cypress/e2e/orangehrm-leave.cy.js
 * Generated by: /tw-e2e-page-object
 *
 * Selector strategy (third-party app — data-testid cannot be added):
 *   1. cy.url()                                          — URL-based (stable)
 *   2. cy.contains('tag', 'text')                        — text-based (moderate)
 *   3. cy.contains('.oxd-label', ...).closest().find()   — label-anchored (stable)
 *   4. button[type]                                      — stable HTML attribute
 *   TODO: If OrangeHRM exposes data-testid on Leave pages, use getByTestId().
 */
class LeavePage {

    // --- Stable selectors ---
    submitButton = 'button[type="submit"]';
    resetButton  = 'button[type="reset"]';

    // --- Assertions ---

    verifyLeaveListPageIsDisplayed() {
        cy.url().should('include', '/leave');
        cy.contains('h5', 'Leave List').should('be.visible');
        return this;
    }

    verifyApplyLeavePageIsDisplayed() {
        cy.url().should('include', '/applyLeave');
        cy.contains('h6', 'Apply Leave').should('be.visible');
        return this;
    }

    verifyLeaveTableIsVisible() {
        cy.get('.oxd-table').should('be.visible');
        return this;
    }

    verifyFormLabelsPresent() {
        cy.contains('.oxd-label', 'Leave Type').should('be.visible');
        cy.contains('.oxd-label', 'From Date').should('be.visible');
        cy.contains('.oxd-label', 'To Date').should('be.visible');
        return this;
    }

    verifyNoLeaveTypesMessage() {
        // The OrangeHRM demo may assign leave types to Admin at any time.
        // Accept either the "no balance" message OR the Leave Type dropdown being present.
        cy.get('body').then(($body) => {
            if ($body.text().includes('No Leave Types with Leave Balance')) {
                cy.contains('No Leave Types with Leave Balance').should('be.visible');
            } else {
                // Admin has leave types assigned — form is shown instead
                cy.contains('.oxd-label', 'Leave Type').should('be.visible');
            }
        });
        return this;
    }

    verifySuccessToast() {
        cy.get('[class*="toast--success"]').should('be.visible');
        return this;
    }

    // --- Actions ---

    selectLeaveType(type) {
        // Label-anchored: finds the Leave Type dropdown by its label
        cy.contains('.oxd-label', 'Leave Type')
            .closest('.oxd-input-group')
            .find('[role="combobox"]')
            .click();
        cy.contains('.oxd-select-option', type).click();
        return this;
    }

    enterFromDate(date) {
        cy.contains('.oxd-label', 'From Date')
            .closest('.oxd-input-group')
            .find('input')
            .clear()
            .type(date);
        return this;
    }

    enterToDate(date) {
        cy.contains('.oxd-label', 'To Date')
            .closest('.oxd-input-group')
            .find('input')
            .clear()
            .type(date);
        return this;
    }

    enterComment(comment) {
        cy.contains('.oxd-label', 'Comments')
            .closest('.oxd-input-group')
            .find('textarea')
            .type(comment);
        return this;
    }

    clickApply() {
        cy.get(this.submitButton).click();
        return this;
    }

    clickReset() {
        cy.get(this.resetButton).click();
        return this;
    }

    hasLeaveTypes() {
        return cy.get('body').then(($body) => $body.find('[role="combobox"]').length > 0);
    }
}

export default new LeavePage();
